def search(query, limit=None, timeout=None, language=None, region=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, random, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0257000" if __import__("os").path.isdir("./environment_mix/0257000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # ---- helpers
    def _parse_intish(x, name):
        if x is None:
            return None
        if isinstance(x, bool):
            return _err("VALIDATION_ERROR", f"{name} must be a number")
        if isinstance(x, (int,)):
            return int(x)
        if isinstance(x, float):
            if x != x or x in (float("inf"), float("-inf")):
                return _err("VALIDATION_ERROR", f"{name} must be a finite number")
            if int(x) != x:
                return _err("VALIDATION_ERROR", f"{name} must be an integer")
            return int(x)
        return _err("VALIDATION_ERROR", f"{name} must be a number")

    def _month_start(dt):
        return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    def _get_or_create_bucket(buckets, workspace_id, api_key_id, period_start_iso):
        for b in buckets:
            if b.get("workspace_id") == workspace_id and b.get("api_key_id") == api_key_id and b.get("period") == "month" and b.get("period_start") == period_start_iso:
                return b
        bid = "ub_" + uuid.uuid4().hex
        b = {
            "id": bid,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "period": "month",
            "period_start": period_start_iso,
            "requests_count": 0,
            "results_count": 0,
            "timeouts_count": 0,
            "failures_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        buckets.append(b)
        return b

    def _resolve_auth():
        # Ambient auth: find any active api key whose workspace is active and usable.
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if not ws or ws.get("status") != "active":
                continue
            # enforce key constraints for rate_limit_rpm/max_timeout_ms being present/valid-ish
            rpm = k.get("rate_limit_rpm")
            mt = k.get("max_timeout_ms")
            if not isinstance(rpm, int) or not (1 <= rpm <= 6000):
                continue
            if not isinstance(mt, int) or not (1000 <= mt <= 120000):
                continue
            candidates.append((ws, k))
        if not candidates:
            return None, None
        # Pick the candidate with highest remaining monthly headroom heuristically
        buckets = _load("usage_buckets.json")
        ms = _month_start(now)
        ms_iso = ms.isoformat().replace("+00:00", "Z")
        best = None
        best_score = None
        for ws, k in candidates:
            # workspace aggregate bucket (api_key_id null) and per-key bucket exist; quota is workspace-level
            # we'll compute workspace aggregate usage for this month
            req_used = 0
            res_used = 0
            for b in buckets:
                if not isinstance(b, dict):
                    continue
                if b.get("workspace_id") == ws.get("id") and b.get("api_key_id") is None and b.get("period") == "month" and b.get("period_start") == ms_iso:
                    req_used = int(b.get("requests_count") or 0)
                    res_used = int(b.get("results_count") or 0)
                    break
            req_quota = int(ws.get("monthly_request_quota") or 0)
            res_quota = int(ws.get("monthly_result_quota") or 0)
            score = (req_quota - req_used) + (res_quota - res_used) / 1000.0
            if best is None or score > best_score:
                best = (ws, k)
                best_score = score
        return best

    def _check_rate_limit(api_key, endpoint_name, api_key_id_for_log):
        # Per-key RPM based on successful+failed calls within last 60s to this endpoint.
        logs = _load("request_logs.json")
        if not logs:
            logs = _load("audit_logs.json")
        if not isinstance(logs, list):
            logs = []
        rpm = int(api_key.get("rate_limit_rpm") or 0)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id_for_log:
                continue
            if r.get("endpoint") != endpoint_name:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= window_start:
                cnt += 1
        if rpm and cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm)
        return None

    def _log_call(endpoint, api_key_id, workspace_id, status, latency_ms, extra=None):
        # Best-effort: store in request_logs.json if exists, else create it.
        fname = "request_logs.json"
        existing = _load(fname)
        if not isinstance(existing, list):
            existing = []
        rid = "rl_" + uuid.uuid4().hex
        row = {
            "id": rid,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": now_iso,
        }
        if isinstance(extra, dict):
            row.update(extra)
        existing.append(row)
        _save(fname, existing)

    # ---- validate input
    if not isinstance(query, str):
        # cannot log without auth; still attempt to resolve so logs/counters move
        ws, k = _resolve_auth()
        if k and ws:
            _log_call("search", k["id"], ws["id"], "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "query must be a string")

    q = query.strip()
    if not q:
        ws, k = _resolve_auth()
        if k and ws:
            _log_call("search", k["id"], ws["id"], "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "query must be non-empty")

    lim = _parse_intish(limit, "limit")
    if isinstance(lim, dict) and lim.get("error"):
        ws, k = _resolve_auth()
        if k and ws:
            _log_call("search", k["id"], ws["id"], "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return lim
    if lim is None:
        lim = 10
    if not (1 <= lim <= 100):
        ws, k = _resolve_auth()
        if k and ws:
            _log_call("search", k["id"], ws["id"], "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "limit out of range (1..100)")

    tout = _parse_intish(timeout, "timeout")
    if isinstance(tout, dict) and tout.get("error"):
        ws, k = _resolve_auth()
        if k and ws:
            _log_call("search", k["id"], ws["id"], "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return tout
    if tout is None:
        tout = 60000

    if language is not None and not isinstance(language, str):
        ws, k = _resolve_auth()
        if k and ws:
            _log_call("search", k["id"], ws["id"], "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "language must be a string")
    if region is not None and not isinstance(region, str):
        ws, k = _resolve_auth()
        if k and ws:
            _log_call("search", k["id"], ws["id"], "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "region must be a string")

    # ---- auth resolve
    resolved = _resolve_auth()
    if not resolved or resolved == (None, None):
        # Cannot serve without an active key/workspace combination
        return _err("UNAUTHORIZED", "No active API key/workspace available")
    ws, api_key = resolved
    workspace_id = ws["id"]
    api_key_id = api_key["id"]

    # ---- rate limit
    rl = _check_rate_limit(api_key, "search", api_key_id)
    if rl:
        _log_call("search", api_key_id, workspace_id, "RATE_LIMIT", (time.time() - t0) * 1000)
        return rl

    # ---- apply defaults for language/region from workspace
    lang = (language.strip() if isinstance(language, str) else "") or (ws.get("default_language") or "") or "zh-CN"
    reg = (region.strip() if isinstance(region, str) else "") or (ws.get("default_region") or "") or "cn"
    if not isinstance(lang, str) or not lang:
        _log_call("search", api_key_id, workspace_id, "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "language must be non-empty")
    if not isinstance(reg, str) or not reg:
        _log_call("search", api_key_id, workspace_id, "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "region must be non-empty")

    # ---- clamp/reject timeout to key max
    max_timeout = int(api_key.get("max_timeout_ms") or 120000)
    allowed_max = min(120000, max_timeout)
    if not (1000 <= tout <= allowed_max):
        _log_call("search", api_key_id, workspace_id, "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", f"timeout out of range (1000..{allowed_max})")

    # ---- quota checks (workspace monthly_request_quota before execution)
    buckets = _load("usage_buckets.json")
    if not isinstance(buckets, list):
        buckets = []
    ms = _month_start(now)
    ms_iso = ms.isoformat().replace("+00:00", "Z")

    ws_bucket = _get_or_create_bucket(buckets, workspace_id, None, ms_iso)
    key_bucket = _get_or_create_bucket(buckets, workspace_id, api_key_id, ms_iso)

    req_quota = int(ws.get("monthly_request_quota") or 0)
    res_quota = int(ws.get("monthly_result_quota") or 0)
    req_used = int(ws_bucket.get("requests_count") or 0)
    res_used = int(ws_bucket.get("results_count") or 0)

    if req_quota >= 0 and req_used >= req_quota:
        _save("usage_buckets.json", buckets)
        _log_call("search", api_key_id, workspace_id, "QUOTA_EXCEEDED", (time.time() - t0) * 1000)
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded", monthly_request_quota=req_quota)

    # Results quota policy: truncate so results_count never exceeds quota (consistent policy).
    remaining_results = None
    if res_quota >= 0:
        remaining_results = max(0, res_quota - res_used)
    eff_limit = lim
    if remaining_results is not None and eff_limit > remaining_results:
        eff_limit = remaining_results
    if remaining_results is not None and remaining_results <= 0:
        _save("usage_buckets.json", buckets)
        _log_call("search", api_key_id, workspace_id, "QUOTA_EXCEEDED", (time.time() - t0) * 1000)
        return _err("QUOTA_EXCEEDED", "Monthly result quota exceeded", monthly_result_quota=res_quota)

    # ---- caching / dedup window by (workspace_id, request_fingerprint, date)
    fp_src = json.dumps(
        {"query": q, "limit": eff_limit, "timeout_ms": tout, "language": lang, "region": reg},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    request_fingerprint = hashlib.sha256(fp_src.encode("utf-8")).hexdigest()

    queries = _load("search_queries.json")
    if not isinstance(queries, list):
        queries = []
    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []

    today = now.date().isoformat()
    cached_query = None
    cached_results = []
    # find most recent succeeded query for same fingerprint in this workspace, created today, with cache_expires_at future
    for row in reversed(queries):
        if not isinstance(row, dict):
            continue
        if row.get("workspace_id") != workspace_id:
            continue
        if row.get("request_fingerprint") != request_fingerprint:
            continue
        ca = row.get("created_at")
        if not isinstance(ca, str):
            continue
        if not ca.startswith(today):
            continue
        if row.get("status") != "succeeded":
            continue
        ce = row.get("cache_expires_at")
        if not isinstance(ce, str):
            continue
        try:
            ce_dt = datetime.datetime.fromisoformat(ce.replace("Z", "+00:00"))
        except Exception:
            continue
        if ce_dt <= now:
            continue
        # fetch results for that query
        r = [x for x in results if isinstance(x, dict) and x.get("search_query_id") == row.get("id")]
        r.sort(key=lambda x: int(x.get("rank") or 0))
        # must have consecutive ranks from 1 and <= eff_limit
        ok = True
        if len(r) == 0 and eff_limit > 0:
            ok = False
        for i, x in enumerate(r, start=1):
            if int(x.get("rank") or -1) != i:
                ok = False
                break
        if ok:
            cached_query = row
            cached_results = r[:eff_limit]
            break

    # ---- create search_queries row (queued)
    qid = "sq_" + uuid.uuid4().hex
    created_at = now_iso
    query_row = {
        "id": qid,
        "workspace_id": workspace_id,
        "api_key_id": api_key_id,
        "query": q,
        "limit": int(eff_limit),
        "timeout_ms": int(tout),
        "language": lang,
        "region": reg,
        "request_fingerprint": request_fingerprint,
        "status": "queued",
        "served_from_cache": False,
        "cache_expires_at": None,
        "http_status_code": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "created_at": created_at,
        "updated_at": created_at,
    }
    queries.append(query_row)

    # transition queued -> running
    started = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    started_iso = started.isoformat().replace("+00:00", "Z")
    query_row["status"] = "running"
    query_row["started_at"] = started_iso
    query_row["updated_at"] = started_iso

    served_from_cache = cached_query is not None
    stored_results = []
    status_final = None
    http_status = 200
    err_code = None
    err_msg = None

    # ---- simulate upstream (offline) with deterministic pseudo-results; also support cache
    if served_from_cache:
        # still must store results rows linked to this new query id
        query_row["served_from_cache"] = True
        cache_expires = now + datetime.timedelta(minutes=30)
        query_row["cache_expires_at"] = cache_expires.isoformat().replace("+00:00", "Z")

        # create new search_results based on cached_results
        for i, r in enumerate(cached_results, start=1):
            sid = "sr_" + uuid.uuid4().hex
            stored_results.append({
                "id": sid,
                "search_query_id": qid,
                "rank": i,
                "title": r.get("title"),
                "url": r.get("url"),
                "display_url": r.get("display_url"),
                "snippet": r.get("snippet"),
                "source": "google",
                "raw": r.get("raw"),
                "created_at": now_iso,
                "updated_at": now_iso,
            })
        status_final = "succeeded"
    else:
        # respect timeout: if very small relative to workload, time out (simple deterministic rule)
        # We'll simulate duration based on query length and limit.
        simulated_work_ms = 50 * min(100, max(1, len(q))) + 30 * int(eff_limit)
        # Random-like but deterministic jitter
        jitter = int(hashlib.md5((q + lang + reg).encode("utf-8")).hexdigest()[:4], 16) % 200
        simulated_work_ms = min(20000, simulated_work_ms + jitter)

        if tout < 1500 and simulated_work_ms > tout:
            status_final = "timed_out"
            http_status = 504
            err_code = "timeout"
            err_msg = "Search timed out"
        else:
            # create pseudo results up to eff_limit; ensure uniqueness by url
            base = "https://www.google." + reg.strip().lstrip(".")
            for i in range(1, int(eff_limit) + 1):
                sid = "sr_" + uuid.uuid4().hex
                url = base + "/search?q=" + urllib.parse.quote(q) + "&rank=" + str(i)
                stored_results.append({
                    "id": sid,
                    "search_query_id": qid,
                    "rank": i,
                    "title": f"{q} - Result {i}",
                    "url": url,
                    "display_url": urllib.parse.urlparse(url).netloc,
                    "snippet": f"Snippet for '{q}' (rank {i}) in {lang}/{reg}.",
                    "source": "google",
                    "raw": {"q": q, "rank": i, "lang": lang, "region": reg},
                    "created_at": now_iso,
                    "updated_at": now_iso,
                })
            status_final = "succeeded"
            cache_expires = now + datetime.timedelta(minutes=30)
            query_row["cache_expires_at"] = cache_expires.isoformat().replace("+00:00", "Z")

    # ---- finalize query row (running -> terminal)
    finished = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    finished_iso = finished.isoformat().replace("+00:00", "Z")

    query_row["status"] = status_final
    query_row["http_status_code"] = http_status
    query_row["error_code"] = err_code
    query_row["error_message"] = err_msg
    query_row["finished_at"] = finished_iso
    # duration_ms = finished - started in ms
    try:
        started_dt = datetime.datetime.fromisoformat(query_row["started_at"].replace("Z", "+00:00"))
        finished_dt = datetime.datetime.fromisoformat(query_row["finished_at"].replace("Z", "+00:00"))
        dur_ms = int((finished_dt - started_dt).total_seconds() * 1000)
        if dur_ms < 0:
            dur_ms = 0
    except Exception:
        dur_ms = None
    query_row["duration_ms"] = dur_ms
    query_row["updated_at"] = finished_iso

    # ---- persist results if succeeded (or cache-succeeded); no results stored for failed/timed_out/cancelled
    if status_final == "succeeded":
        # enforce consecutive ranks starting at 1 and N<=limit
        for idx, rr in enumerate(stored_results, start=1):
            rr["rank"] = idx
        # enforce uniqueness constraints within query by rank/url (best effort: de-dupe)
        seen_rank = set()
        seen_url = set()
        final_results = []
        for rr in stored_results:
            rk = int(rr.get("rank") or 0)
            u = rr.get("url")
            if rk < 1 or not isinstance(u, str) or not u.strip():
                continue
            if rk in seen_rank or u in seen_url:
                continue
            seen_rank.add(rk)
            seen_url.add(u)
            final_results.append(rr)
        # ensure ranks consecutive
        final_results.sort(key=lambda x: int(x["rank"]))
        consec = []
        for i, rr in enumerate(final_results, start=1):
            if int(rr["rank"]) != i:
                break
            consec.append(rr)
        final_results = consec[: int(query_row["limit"])]
        # if truncation reduced to 0 while limit > 0, that's allowed only if quota truncated to 0 (handled earlier)
        results.extend(final_results)

        # ---- usage increments after completion
        returned_n = len(final_results)
        ws_bucket["requests_count"] = int(ws_bucket.get("requests_count") or 0) + 1
        key_bucket["requests_count"] = int(key_bucket.get("requests_count") or 0) + 1
        ws_bucket["results_count"] = int(ws_bucket.get("results_count") or 0) + returned_n
        key_bucket["results_count"] = int(key_bucket.get("results_count") or 0) + returned_n
        ws_bucket["updated_at"] = now_iso
        key_bucket["updated_at"] = now_iso
        # enforce never exceed result quota due to truncation logic
        if res_quota >= 0 and int(ws_bucket["results_count"]) > res_quota:
            # rollback results addition and mark failed for integrity
            # (shouldn't happen, but must not raise)
            # Remove inserted results for this query id.
            results = [r for r in results if not (isinstance(r, dict) and r.get("search_query_id") == qid)]
            ws_bucket["results_count"] = min(int(ws_bucket.get("results_count") or 0), res_quota)
            key_bucket["results_count"] = max(0, int(key_bucket.get("results_count") or 0) - returned_n)
            query_row["status"] = "failed"
            query_row["http_status_code"] = 409
            query_row["error_code"] = "quota_invariant_violation"
            query_row["error_message"] = "Result quota invariant violated"
    elif status_final == "timed_out":
        ws_bucket["requests_count"] = int(ws_bucket.get("requests_count") or 0) + 1
        key_bucket["requests_count"] = int(key_bucket.get("requests_count") or 0) + 1
        ws_bucket["timeouts_count"] = int(ws_bucket.get("timeouts_count") or 0) + 1
        key_bucket["timeouts_count"] = int(key_bucket.get("timeouts_count") or 0) + 1
        ws_bucket["updated_at"] = now_iso
        key_bucket["updated_at"] = now_iso
    else:
        ws_bucket["requests_count"] = int(ws_bucket.get("requests_count") or 0) + 1
        key_bucket["requests_count"] = int(key_bucket.get("requests_count") or 0) + 1
        ws_bucket["failures_count"] = int(ws_bucket.get("failures_count") or 0) + 1
        key_bucket["failures_count"] = int(key_bucket.get("failures_count") or 0) + 1
        ws_bucket["updated_at"] = now_iso
        key_bucket["updated_at"] = now_iso

    # ---- persist all
    _save("search_queries.json", queries)
    _save("search_results.json", results)
    _save("usage_buckets.json", buckets)

    # last_used_at on successful calls only (status succeeded)
    if query_row.get("status") == "succeeded":
        api_keys_all = _load("api_keys.json")
        if isinstance(api_keys_all, list):
            for k in api_keys_all:
                if isinstance(k, dict) and k.get("id") == api_key_id:
                    k["last_used_at"] = now_iso
                    k["updated_at"] = now_iso
                    break
            _save("api_keys.json", api_keys_all)

    latency_ms = (time.time() - t0) * 1000
    _log_call("search", api_key_id, workspace_id, query_row.get("status") or "unknown", latency_ms, extra={"search_query_id": qid})

    # ---- response envelope
    resp_items = []
    if query_row.get("status") == "succeeded":
        # Return normalized items from stored rows
        resp_items = [r for r in results if isinstance(r, dict) and r.get("search_query_id") == qid]
        resp_items.sort(key=lambda x: int(x.get("rank") or 0))
        resp_items = [{
            "rank": int(r.get("rank") or 0),
            "title": r.get("title"),
            "url": r.get("url"),
            "display_url": r.get("display_url"),
            "snippet": r.get("snippet"),
            "source": r.get("source"),
        } for r in resp_items]

    return {
        "search_query": query_row,
        "results": resp_items,
        "meta": {
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "served_from_cache": bool(query_row.get("served_from_cache")),
            "returned": len(resp_items),
            "requested_limit": lim,
            "effective_limit": int(query_row.get("limit") or 0),
        },
    }

def list_search_queries(status=None, served_from_cache=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0257000" if __import__("os").path.isdir("./environment_mix/0257000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
