            row["error_code"] = error_code
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate input
    if not isinstance(id, str) or not id.strip():
        _log("VALIDATION_ERROR", None, None, "invalid_param", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.")
    qid = id.strip()

    # Load data (support both list-root and {"rows":[...]} file shapes)
    api_keys = _as_rows(_load("api_keys.json"))
    workspaces = _as_rows(_load("workspaces.json"))
    queries = _as_rows(_load("search_queries.json"))
    results = _as_rows(_load("search_results.json"))

    # Find query
    qrow = None
    for r in queries:
        if isinstance(r, dict) and r.get("id") == qid:
            qrow = r
            break

    if not qrow:
        _log("NOT_FOUND", None, None, "not_found", "search query id not found")
