    # Resolve workspace and API key from the query
    workspace_id = qrow.get("workspace_id")
    api_key_id = qrow.get("api_key_id")

    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break

    ak = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
