            break

    # Enforce referential integrity / auth prerequisites
    if not ws or ws.get("status") != "active":
        _log("UNAUTHORIZED", api_key_id, workspace_id, "unauthorized", "workspace missing or not active for this query")
        return _err("UNAUTHORIZED", "Unauthorized: no active workspace context available for this request.")
