        _log("UNAUTHORIZED", api_key_id, workspace_id, "unauthorized", "workspace mismatch between query and api key")
        return _err("UNAUTHORIZED", "Unauthorized: workspace mismatch.")

    # Ambient auth: pick a working authenticated API key/workspace combination.
    # Since the tool signature carries no credential, accept if ANY active key exists for this workspace.
    has_any_active_key_for_ws = any(
        isinstance(k, dict) and k.get("status") == "active" and k.get("workspace_id") == workspace_id
        for k in api_keys
    )
    if not has_any_active_key_for_ws:
        _log("UNAUTHORIZED", api_key_id, workspace_id, "unauthorized", "no active api key for workspace")
        return _err("UNAUTHORIZED", "Unauthorized: no active API key available.")

    # Attach results (best-effort; reads return empty set if none)
    q_results = []
    for rr in results:
        if isinstance(rr, dict) and rr.get("search_query_id") == qid:
            q_results.append(rr)
    q_results.sort(key=lambda x: x.get("rank") if isinstance(x.get("rank"), int) else 10**9)

    # Update last_used_at for the query's api key (successful read counts as use)
