    # Update last_used_at for key and persist
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    _log("OK", api_key_id, workspace_id, None, None)
    return {"search_query": updated}

def get_usage_bucket(period=None, period_start=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0257000" if __import__("os").path.isdir("./environment_mix/0257000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso_z(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _log(endpoint, api_key_id, workspace_id, status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "rl_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status_code,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "timestamp": _iso_z(now),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate inputs (relaxed: accept any YYYY-MM-DD and normalize to month start)
    if period is None:
        period = "month"
    if not isinstance(period, str) or period != "month":
        return _err("VALIDATION_ERROR", "Parameter 'period' must be 'month'.")
    if period_start is not None and not isinstance(period_start, str):
        return _err("VALIDATION_ERROR", "Parameter 'period_start' must be a date string (YYYY-MM-DD) when provided.")

    # Resolve requested period_start (month bucket start at 00:00:00Z)
    if period_start is None:
        ps_dt = datetime.datetime(now.year, now.month, 1, 0, 0, 0, tzinfo=datetime.timezone.utc)
    else:
        s = period_start.strip()
        try:
            # accept date only; if a datetime is passed, take its date
            if "T" in s:
                # accept ISO datetime
                if s.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(s[:-1] + "+00:00")
                else:
                    dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
                ps_dt = datetime.datetime(dt.year, dt.month, 1, 0, 0, 0, tzinfo=datetime.timezone.utc)
            else:
                y, m, d = s.split("-")
                y = int(y); m = int(m); d = int(d)
                # normalize to month start even if not day 1 (accept vendor args seen in audit)
                ps_dt = datetime.datetime(y, m, 1, 0, 0, 0, tzinfo=datetime.timezone.utc)
        except Exception:
            return _err("VALIDATION_ERROR", "Parameter 'period_start' must be a valid date string (YYYY-MM-DD).")

    ps_iso = _iso_z(ps_dt)

    # Ambient auth: active key + active workspace required
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    ws_by = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
    chosen_k = None
    chosen_ws = None
    for k in api_keys if isinstance(api_keys, list) else []:
        if not isinstance(k, dict) or k.get("status") != "active":
            continue
        ws = ws_by.get(k.get("workspace_id"))
        if ws and ws.get("status") == "active":
            chosen_k, chosen_ws = k, ws
            break
    if not chosen_k or not chosen_ws:
        _log("get_usage_bucket", None, None, "UNAUTHORIZED", "no_active_key")
        return _err("UNAUTHORIZED", "No active API key/workspace is available to authorize this request.")

    workspace_id = chosen_ws.get("id")
    api_key_id = chosen_k.get("id")

    buckets = _load("usage_buckets.json")
    if not isinstance(buckets, list):
        buckets = []

    # Find per-key bucket first; fallback to workspace aggregate (api_key_id null) for same period
    per_key = None
    ws_agg = None
    for b in buckets:
        if not isinstance(b, dict):
            continue
        if b.get("workspace_id") != workspace_id:
            continue
        if b.get("period") != "month":
            continue
        if b.get("period_start") != ps_iso:
            continue
        if b.get("api_key_id") == api_key_id:
            per_key = b
            break
        if b.get("api_key_id") is None:
            ws_agg = b

    result_bucket = per_key if per_key is not None else ws_agg
    if result_bucket is None:
        # reads matching nothing should return empty result (not an error)
        _log("get_usage_bucket", api_key_id, workspace_id, "OK", None)
        return {
            "usage_bucket": None,
            "period": "month",
            "period_start": ps_iso,
        }

    # Update api key last_used_at for successful read
    chosen_k["last_used_at"] = _iso_z(now)
    chosen_k["updated_at"] = _iso_z(now)
    for i, kk in enumerate(api_keys):
        if isinstance(kk, dict) and kk.get("id") == api_key_id:
            api_keys[i] = chosen_k
            break
    _save("api_keys.json", api_keys)

    _log("get_usage_bucket", api_key_id, workspace_id, "OK", None)
    return {"usage_bucket": result_bucket}
